"""Local, customer-scoped multi-product selection and review workbench."""

MULTI_PRODUCT_PAGE = """<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>多产品混合图</title><style>
body{font-family:system-ui,"PingFang SC",sans-serif;background:#f6f2ec;color:#29231f;margin:0}.wrap{max-width:980px;margin:auto;padding:36px 20px}.panel{background:#fff;border:1px solid #e2d9ce;border-radius:16px;padding:20px;margin:14px 0}.notice{background:#fff6df;border-color:#e7ce98}.grid,.results{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px}.item{border:1px solid #e2d9ce;border-radius:12px;padding:11px}.item img{width:100%;aspect-ratio:1;object-fit:contain;background:#f7f4ef;border-radius:9px}.item label{display:flex;gap:7px}.item button,button{padding:10px 13px;border:0;border-radius:9px;background:#29231f;color:#fff;cursor:pointer;margin:4px}input,select{padding:9px;border:1px solid #d8cec2;border-radius:8px}.muted{color:#746b63}.ok{color:#246b49;font-weight:700}.error{color:#a33}.actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
</style></head><body><main class="wrap"><p><a href="/local/style-suite/output-center">← 返回内容输出中心</a></p><h1>多产品混合图</h1><section class="panel notice"><strong>边界：</strong>只允许手动选择 2–5 件不同商品。系统会逐件记录来源，候选图不可直接发布；真实模型未获单次授权时会停止，不会偷偷扣费。</section><section class="panel"><div class="actions"><label>客户ID <input id="customer" size="38"></label><button id="load">读取我的商品库</button></div><p id="status" class="muted">请选择客户后读取商品。</p><div id="assets" class="grid"></div></section><section id="style-panel" class="panel" hidden><label>场景与风格 <select id="style"></select></label><button id="generate">生成 3 张待审候选</button><p class="muted">先执行本地规则检查，再由你选择采用或退回。</p></section><section id="result-panel" class="panel" hidden><h2>候选审核</h2><div id="results" class="results"></div></section></main><script>
const customer=document.querySelector('#customer'),load=document.querySelector('#load'),assets=document.querySelector('#assets'),statusNode=document.querySelector('#status'),stylePanel=document.querySelector('#style-panel'),style=document.querySelector('#style'),generate=document.querySelector('#generate'),resultPanel=document.querySelector('#result-panel'),results=document.querySelector('#results');const params=new URLSearchParams(location.search);customer.value=params.get('benchmark_customer_id')||localStorage.getItem('style-suite-customer-id')||'';let library=[],plan;
const headers=()=>({'X-Customer-Id':customer.value.trim()});async function json(url,options={}){const response=await fetch(url,{...options,headers:{...headers(),...(options.headers||{})}}),body=await response.json();if(!response.ok)throw Error(body.error?.code||`HTTP_${response.status}`);return body}
load.onclick=async()=>{assets.replaceChildren();stylePanel.hidden=true;resultPanel.hidden=true;try{library=await json('/local/style-suite/api/multi-product/options');statusNode.textContent=library.length?'请选择 2–5 件不同商品。':'商品库暂无已确认且已授权转换的商品。';for(const x of library){const card=document.createElement('article');card.className='item';card.innerHTML=`<img alt="${x.product_id}"><label><input type="checkbox" value="${x.asset_id}"> <span>${x.product_id}</span></label>`;assets.append(card);const response=await fetch(x.content_url,{headers:headers()}),blob=await response.blob();card.querySelector('img').src=URL.createObjectURL(blob)}assets.onchange=prepareStyles}catch(error){statusNode.className='error';statusNode.textContent='读取失败：'+error.message}};
async function prepareStyles(){const chosen=selected();stylePanel.hidden=true;if(chosen.length<2||chosen.length>5){statusNode.textContent=`已选 ${chosen.length} 件；必须选 2–5 件。`;return}try{plan=await json('/v1/style-suites/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({product_id:chosen[0].product_id,source_asset_id:chosen[0].asset_id})});style.replaceChildren();for(const item of plan.items){const option=document.createElement('option');option.value=JSON.stringify(item);option.textContent=`${item.style_name} · ${item.slot_key}`;style.append(option)}stylePanel.hidden=!plan.items.length;statusNode.textContent=plan.items.length?`已选 ${chosen.length} 件，选择场景后生成。`:'尚无已确认的场景风格。'}catch(error){statusNode.className='error';statusNode.textContent='风格准备失败：'+error.message}}
function selected(){const ids=[...assets.querySelectorAll('input:checked')].map(x=>x.value);return ids.map(id=>library.find(x=>x.asset_id===id)).filter(Boolean)}
generate.onclick=async()=>{const chosen=selected(),item=JSON.parse(style.value),ratio=item.slot_snapshot.rules.aspect_ratio||'4:5';generate.disabled=true;results.replaceChildren();try{const job=await json('/v1/image-outputs/multi-product',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sources:chosen.map(x=>({product_id:x.product_id,asset_id:x.asset_id})),scene_style_id:item.scene_style_id,style_card_version_id:item.scene_style_version_id,output_ratio:ratio,slot_key:item.slot_key,idempotency_key:`browser-multi-${crypto.randomUUID()}`})}),gate=await json(`/v1/image-outputs/${job.id}/authenticity-checks`,{method:'POST'});resultPanel.hidden=false;for(const candidate of gate.candidates){const card=document.createElement('article');card.className='item';card.innerHTML=`<img alt="多商品候选 ${candidate.sequence_number}"><p>${candidate.candidate_state==='machine_passed'?'规则检查通过':'规则检查未通过'}</p><button data-decision="approved">采用</button><button data-decision="rejected">退回</button>`;results.append(card);const response=await fetch(`/local/style-suite/api/multi-product/jobs/${job.id}/candidates/${candidate.id}/content`,{headers:headers()}),blob=await response.blob();card.querySelector('img').src=URL.createObjectURL(blob);for(const button of card.querySelectorAll('button'))button.onclick=()=>review(job.id,candidate.id,button.dataset.decision,card)}statusNode.className='ok';statusNode.textContent='已生成并完成本地规则检查；仍需人工审核。'}catch(error){statusNode.className='error';statusNode.textContent='生成停止：'+error.message}finally{generate.disabled=false}};
async function review(jobId,candidateId,decision,card){try{const outcome=await json(`/v1/image-outputs/${jobId}/candidates/${candidateId}/review`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({decision,idempotency_key:`browser-multi-review-${jobId}-${candidateId}-${decision}`,fidelity_warning_acknowledged:false})});card.querySelectorAll('button').forEach(x=>x.disabled=true);const p=document.createElement('p');p.className='ok';p.textContent=outcome.customer_approved?'✓ 已人工采用；仍不可直接发布':'已退回并保留记录';card.append(p)}catch(error){statusNode.className='error';statusNode.textContent='审核保存失败：'+error.message}}
</script></body></html>"""
